Fixpoint tbound {R} (t : stree ev Z R) (cb ck : Z) (P : R -> Prop) {struct t} : Prop :=
  match t with
  | SRet r => P r
  | SVis e k => ev_costb e <= cb /\ ev_costk e <= ck /\
               forall z, ans_cont e z -> tbound (k z) (cb - ev_costb e) (ck - ev_costk e) P
  end.


